class Solution {
public:
    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
        int m = heights.size();
        int n = heights[0].size();
        vector<vector<bool>> pac(m, vector<bool>(n, false));
        vector<vector<bool>> atl(m, vector<bool>(n, false));
        queue<pair<int,int>> q;

        // Pacific borders
        for (int i = 0; i < m; ++i) {
            pac[i][0] = true;
            q.emplace(i, 0);
        }
        for (int j = 1; j < n; ++j) { // start from j=1 to avoid (0,0) twice
            pac[0][j] = true;
            q.emplace(0, j);
        }
        bfs(heights, pac, q);

        // Atlantic borders
        while (!q.empty()) q.pop(); // reuse queue
        for (int i = 0; i < m; ++i) {
            atl[i][n-1] = true;
            q.emplace(i, n-1);
        }
        for (int j = 0; j < n-1; ++j) { // avoid (m-1,n-1) twice
            atl[m-1][j] = true;
            q.emplace(m-1, j);
        }
        bfs(heights, atl, q);

        vector<vector<int>> ans;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (pac[i][j] && atl[i][j])
                    ans.push_back({i, j});
        return ans;
    }

private:
    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    void bfs(const vector<vector<int>>& h,
             vector<vector<bool>>& reach,
             queue<pair<int,int>>& q) {
        int m = h.size(), n = h[0].size();
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (auto &d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (reach[nr][nc]) continue;
                if (h[nr][nc] < h[r][c]) continue; // can only flow uphill
                reach[nr][nc] = true;
                q.emplace(nr, nc);
            }
        }
    }
};
